/**
 * Evolution target gating by native region progress (same rules as egg hatch pools).
 */
import { getEggNativeRegionIdForSpecies } from '../../constants/balance/eggRegionMap.ts';
import { isEggRegionUnlockedForGame } from './regionUnlock.ts';
import type { GameRuntime } from '../types/game.js';

export function isEvolutionTargetUnlockedForProgress(
    game: GameRuntime | null | undefined,
    targetSpecies: string,
): boolean {
    if (!game) return false;
    const regionId = getEggNativeRegionIdForSpecies(targetSpecies) ?? 'kanto';
    return isEggRegionUnlockedForGame(game, regionId);
}
