/**
 * @file src/stores/bagSnapshotDiff.ts
 */

import type {
  BagAutoCatchSnapshot,
  BagEggMetaSnapshot,
  BagInventorySnapshot,
  BagPanelUiSnapshot,
  BagSnapshot,
} from '../bus/snapshots.js';

function cardsEqual(a: BagInventorySnapshot['itemCards'], b: BagInventorySnapshot['itemCards']): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    const ai = a[i];
    const bi = b[i];
    if (ai === undefined || bi === undefined) return false;
    if (ai.itemKey !== bi.itemKey || ai.cardHtml !== bi.cardHtml) return false;
  }
  return true;
}

function autoCatchEqual(a: BagAutoCatchSnapshot, b: BagAutoCatchSnapshot): boolean {
  return (
    a.panelVisible === b.panelVisible
    && a.enabled === b.enabled
    && a.catchShiny === b.catchShiny
    && a.catchRoamer === b.catchRoamer
    && a.catchLegendary === b.catchLegendary
    && a.minChancePct === b.minChancePct
    && a.showBallControls === b.showBallControls
    && a.showMasterballSetting === b.showMasterballSetting
    && a.useMasterballActiveTargets === b.useMasterballActiveTargets
    && a.useMasterballShiny === b.useMasterballShiny
    && a.useMasterballRoamer === b.useMasterballRoamer
    && a.useMasterballLegendary === b.useMasterballLegendary
  );
}

function uiEqual(a: BagPanelUiSnapshot, b: BagPanelUiSnapshot): boolean {
  return (
    a.language === b.language
    && a.porygonTitle === b.porygonTitle
    && a.porygonDesc === b.porygonDesc
    && a.toggleOn === b.toggleOn
    && a.toggleOff === b.toggleOff
    && a.autoCatchActive === b.autoCatchActive
    && a.autoCatchShiny === b.autoCatchShiny
    && a.autoCatchRoamer === b.autoCatchRoamer
    && a.autoCatchLegendary === b.autoCatchLegendary
    && a.autoCatchMinChance === b.autoCatchMinChance
    && a.autoCatchHelp === b.autoCatchHelp
    && a.masterBallImg === b.masterBallImg
    && a.autoCatchMasterTooltipNormal === b.autoCatchMasterTooltipNormal
    && a.autoCatchMasterTooltipShiny === b.autoCatchMasterTooltipShiny
    && a.autoCatchMasterTooltipRoamer === b.autoCatchMasterTooltipRoamer
    && a.autoCatchMasterTooltipLegendary === b.autoCatchMasterTooltipLegendary
    && a.incubatorsTitle === b.incubatorsTitle
    && a.eggInventoryTitle === b.eggInventoryTitle
    && a.inventoryTitle === b.inventoryTitle
    && a.inventoryEmpty === b.inventoryEmpty
    && a.filterAll === b.filterAll
    && a.filterCombat === b.filterCombat
    && a.filterPermanent === b.filterPermanent
    && a.filterHeld === b.filterHeld
    && a.filterKey === b.filterKey
    && a.filterEvolutionStones === b.filterEvolutionStones
    && a.filterBerries === b.filterBerries
    && a.filterCt === b.filterCt
    && a.filterMisc === b.filterMisc
  );
}

function eggSectionsSig(sections: BagSnapshot['eggSections']): string {
  return JSON.stringify(sections);
}

export function bagInventoryWouldChange(prev: BagInventorySnapshot, next: BagInventorySnapshot): boolean {
  return (
    prev.inventoryFilter !== next.inventoryFilter
    || prev.itemTypesCountLabel !== next.itemTypesCountLabel
    || prev.inventoryEmpty !== next.inventoryEmpty
    || prev.inventoryEmptyMessage !== next.inventoryEmptyMessage
    || !cardsEqual(prev.itemCards, next.itemCards)
  );
}

export function bagEggMetaWouldChange(prev: BagEggMetaSnapshot, next: BagEggMetaSnapshot): boolean {
  return (
    prev.eggsTotalCount !== next.eggsTotalCount
    || prev.incubatorBoostText !== next.incubatorBoostText
    || prev.incubatorBoostTitle !== next.incubatorBoostTitle
    || prev.incubatorBoostVisible !== next.incubatorBoostVisible
  );
}

export function bagSnapshotWouldChange(prev: BagSnapshot, next: BagSnapshot): boolean {
  return (
    !uiEqual(prev.ui, next.ui)
    || !autoCatchEqual(prev.autoCatch, next.autoCatch)
    || eggSectionsSig(prev.eggSections) !== eggSectionsSig(next.eggSections)
    || bagInventoryWouldChange(prev, next)
    || bagEggMetaWouldChange(prev, next)
  );
}

export function pickBagInventory(snap: BagSnapshot): BagInventorySnapshot {
  return {
    itemCards: snap.itemCards,
    inventoryFilter: snap.inventoryFilter,
    itemTypesCountLabel: snap.itemTypesCountLabel,
    inventoryEmpty: snap.inventoryEmpty,
    inventoryEmptyMessage: snap.inventoryEmptyMessage,
  };
}

export function pickBagEggMeta(snap: BagSnapshot): BagEggMetaSnapshot {
  return {
    eggsTotalCount: snap.eggsTotalCount,
    incubatorBoostText: snap.incubatorBoostText,
    incubatorBoostTitle: snap.incubatorBoostTitle,
    incubatorBoostVisible: snap.incubatorBoostVisible,
  };
}
